SELECT uniqIf(s.person_id, and(ifNull(greaterOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), 0), ifNull(lessOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))), 0))) AS unique_users, NULL AS previous_unique_users, sumIf(s.page_screen_count, and(ifNull(greaterOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), 0), ifNull(lessOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))), 0))) AS total_filtered_pageview_count, NULL AS previous_total_filtered_pageview_count, countIf(and(ifNull(greaterOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), 0), ifNull(lessOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))), 0))) AS unique_sessions, NULL AS previous_unique_sessions, avgIf(s.session_duration, and(ifNull(greaterOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), 0), ifNull(lessOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))), 0))) AS avg_duration_s, NULL AS previous_avg_duration_s, avgIf(s.is_bounce, and(ifNull(greaterOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), 0), ifNull(lessOrEquals(s.start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))), 0))) AS bounce_rate, NULL AS previous_bounce_rate FROM (SELECT events.properties.`$session_id` AS session_id, any(events.person_id) AS person_id, countIf(or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS page_screen_count, max(equals(events.event, '$autocapture')) AS has_autocapture, dateDiff('second', min(toTimeZone(events.timestamp, 'UTC')), max(toTimeZone(events.timestamp, 'UTC'))) AS session_duration, argMinIf(nullIf(toString(events.properties.`$pathname`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS entry_pathname, argMaxIf(nullIf(toString(events.properties.`$pathname`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS exit_pathname, argMinIf(nullIf(toString(events.properties.`$host`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS entry_host, argMaxIf(nullIf(toString(events.properties.`$host`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS exit_host, fromUnixTimestamp(intDiv(accurateCastOrNull(bitShiftRight(any(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), 80), 'Int64'), 1000)) AS start_timestamp, if(equals(page_screen_count, 0), NULL, not(or(greaterOrEquals(page_screen_count, 2), has_autocapture, greaterOrEquals(session_duration, 10)))) AS is_bounce FROM events_json AS events WHERE and(equals(events.team_id, TEAM_ID), and(isNotNull(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1)) GROUP BY session_id HAVING greater(page_screen_count, 0)) AS s LIMIT 50000
